package com.classvoice.controller; import com.classvoice.dao.LectureDAO; import com.classvoice.model.*; import com.classvoice.util.WebUtil; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import jakarta.servlet.*; import java.io.IOException; import java.time.LocalDate;
@WebServlet("/teacher/lecture/create") public class CreateLectureServlet extends HttpServlet {protected void doPost(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{String title=WebUtil.trim(r.getParameter("title")),desc=WebUtil.trim(r.getParameter("description")),date=WebUtil.trim(r.getParameter("lectureDate"));String err=null;LocalDate d=null;if(title.length()<3||title.length()>180)err="Title must be between 3 and 180 characters.";try{if(err==null)d=LocalDate.parse(date);}catch(Exception e){err="Enter a valid lecture date.";}if(err==null&&desc.length()>500)err="Description is too long.";if(err!=null){r.setAttribute("error",err);r.getRequestDispatcher("/WEB-INF/views/create-lecture.jsp").forward(r,p);return;}try{User u=(User)r.getSession().getAttribute("user");Lecture l=new Lecture();l.setTeacherId(u.getUserId());l.setTitle(title);l.setDescription(desc);l.setLectureDate(d);long id=new LectureDAO().create(l);p.sendRedirect(r.getContextPath()+"/teacher/topics?lectureId="+id);}catch(Exception e){throw new ServletException(e);}}}
